contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run will: set MinSum and LogFile, put funds into c from this contract, then attempt Collect
    // params: lockTime for Put, amount to send with Put (putAmount), collect amount (collectAmount)
    // require this contract has enough balance to fund the Put
    function run(uint _lockTime, uint putAmount, uint collectAmount, address logAddr, uint minSum) public payable {
        require(address(this).balance >= putAmount, "need funds to Put");
        // initialize MinSum and LogFile before Initialized is called; both calls must be allowed to set values
        // SetMinSum and SetLogFile are nonReentrant_ and only allowed before intitalized=true
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        // make a Put to deposit funds for this contract's address (InvMutTest) into c
        uint beforeAccBalance = c.Acc(address(this)).balance; // read auto-generated getter
        uint beforeContractBalance = address(c).balance;

        // perform Put sending putAmount wei
        c.Put{value: putAmount}(_lockTime);

        // after put, read balances
        uint afterAccBalance = c.Acc(address(this)).balance;
        uint afterContractBalance = address(c).balance;

        // Sanity: the recorded balance must have increased by putAmount
        // (this is not the final assert; just a runtime check to ensure progression — if it fails, test will revert)
        require(afterAccBalance >= beforeAccBalance);

        // Now try Collect of collectAmount. We capture whether it reverts.
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balance after Collect attempt
        uint finalAccBalance = c.Acc(address(this)).balance;
        uint finalContractBalance = address(c).balance;

        // General property asserted: if Collect did NOT revert, then recorded balance decreased by exactly collectAmount
        // and the contract's balance decreased by at least collectAmount (since collect may transfer out eth)
        assert(
            reverted || (
                // note: use >= to avoid underflow; exact decrease on Acc balance
                finalAccBalance + collectAmount == afterAccBalance
                && finalContractBalance + collectAmount <= afterContractBalance
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will deposit into c using this contract (so msg.sender in c calls is this contract).
    // Parameters:
    //  putAmount - wei to send with Put (must be available in this contract)
    //  lockTime - lock time passed to Put
    //  collectAmount - amount to attempt to Collect
    //  logAddr - address to set as LogFile
    //  minSum - value to set as MinSum
    function run(uint lockTime, uint putAmount, uint collectAmount, address logAddr, uint minSum) public payable {
        // ensure this test contract has funds to perform the Put
        require(address(this).balance >= putAmount, "insufficient balance for Put");

        // initialize MinSum and LogFile before calling Initialized()
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);

        // read before-values that are publicly observable
        // Note: Acc is a public mapping returning (uint unlockTime, uint balance) tuple
        (uint beforeUnlock, uint beforeAccBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // perform Put to deposit putAmount into c for this contract
        c.Put{value: putAmount}(lockTime);

        // read after Put values
        (uint midUnlock, uint midAccBal) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // ensure that balance observed increased by at least putAmount
        require(midAccBal >= beforeAccBal);
        require(midContractBal >= beforeContractBal);

        // Attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-Collect values
        (uint afterUnlock, uint afterAccBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General property: if Collect did not revert, then the recorded acc balance decreased by exactly collectAmount
        // and the contract's balance decreased by at least collectAmount.
        assert(
            reverted || (
                // recorded balance decreased exactly by collectAmount
                afterAccBal + collectAmount == midAccBal
                // contract balance decreased by at least collectAmount (use + to avoid underflow)
                && afterContractBal + collectAmount <= midContractBal
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test: ensure Put never decreases balances
    // params:
    //  lockTime: passed to Put
    //  putAmount: wei to send with Put (must be available on this contract)
    function run(uint lockTime, uint putAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient balance for Put");

        // Read observable balances before
        (uint beforeUnlock, uint beforeAccBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Perform Put sending putAmount wei
        c.Put{value: putAmount}(lockTime);

        // Read observable balances after
        (uint afterUnlock, uint afterAccBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General invariant: Put must not decrease the recorded balance nor the contract balance;
        // recorded Acc balance increases by at least putAmount (or stays the same only if putAmount==0),
        // and contract's ether balance increases by at least putAmount.
        // Expressed without subtraction to avoid under/overflow in the test.
        assert(
            afterAccBal >= beforeAccBal && afterContractBal >= beforeContractBal &&
            // ensure the observed increases cover the sent amount
            (afterAccBal >= beforeAccBal + putAmount || putAmount == 0) &&
            (afterContractBal >= beforeContractBal + putAmount || putAmount == 0)
        );
    }

    // receive so this contract can hold and forward funds
    receive() external payable {}
}

