contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: set MinSum and LogFile and initialize to allow Put and Collect behavior,
    // then Put some ether from this contract into c for msg.sender==address(this) (InvMutTest),
    // then attempt Collect and check that on successful external send the stored balance and c balance both decreased by _am.
    function run(address logAddress, uint minSum, uint lockTime, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount + 1 wei); // ensure we can fund Put (and keep some gas)
        // set MinSum and LogFile and initialize on fresh c
        // these calls are top-level and can revert; we don't catch them because if they revert the assert won't be reached
        c.SetLogFile(logAddress);
        c.SetMinSum(minSum);
        c.Initialized();

        // read before-values
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint cBeforeBal = address(c).balance;

        // deposit funds into c as msg.sender==this contract
        c.Put{value: putAmount}(lockTime);

        // read after deposit
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint cMidBal = address(c).balance;

        // try Collect and record whether it reverted and whether internal call to msg.sender succeeded.
        bool reverted;
        bool callSucceeded;
        // Collect is payable in source but doesn't need value; call and catch to detect revert
        try c.Collect(collectAmount) {
            reverted = false;
            // If Collect did not revert, we cannot observe whether the low-level send to msg.sender succeeded except via balances.
            callSucceeded = true;
        } catch {
            reverted = true;
            callSucceeded = false;
        }

        // read after attempted collect
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint cAfterBal = address(c).balance;
        uint thisAfterBal = address(this).balance;

        // General rule: If Collect did NOT revert and the contract's recorded balance decreased by some amount, then that decrease equals collectAmount
        // and the contract's ether balance decreased by the same amount. This captures that on successful Collect the amount is transferred out and state updated accordingly.
        // We express it as: if not reverted and midBalance >= collectAmount and midBalance - afterBalance == collectAmount then cMidBal - cAfterBal == collectAmount.
        // Also ensure that when Collect didn't revert but preconditions weren't met, nothing was changed (defensive): if reverted==false then midBalance >= collectAmount && midBalance >= minSumCheck implies consistent.

        // Note: avoid underflow in the assert by using comparisons and additions.
        assert(
            // Case A: call reverted -> we don't claim anything about balances
            reverted
            || (
                // Collect did not revert: then the stored balance decreased by exactly collectAmount iff it was allowed and the contract balance decreased equally
                // First require midBalance >= collectAmount (otherwise Collect should have reverted per contract), and block.timestamp > midUnlock cannot be checked here,
                // but we can still assert that if the recorded balance decreased, it decreased by exactly collectAmount and c's balance decreased equally.
                (
                    // If recorded balance changed, it must have decreased by exactly collectAmount and c balance decreased same amount
                    (midBalance != afterBalance) -> (midBalance > afterBalance && midBalance - afterBalance == collectAmount && cMidBal - cAfterBal == collectAmount)
                )
            )
        );
    }

    // helper for implication using Solidity (a -> b) is (!a || b). Define as internal pure via inline expression in assert using that pattern.
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: logAddress and minSum and lockTime and putAmount and collectAmount
    function run(address logAddress, uint minSum, uint lockTime, uint putAmount, uint collectAmount) public payable {
        // need funds to deposit
        require(address(this).balance >= putAmount);

        // initialize c so Put/Collect behavior is enabled
        c.SetLogFile(logAddress);
        c.SetMinSum(minSum);
        c.Initialized();

        // read before-values
        (, uint beforeBalance) = c.Acc(address(this));
        uint cBeforeBal = address(c).balance;

        // deposit funds into c as msg.sender == this contract
        c.Put{value: putAmount}(lockTime);

        // read after deposit
        (, uint midBalance) = c.Acc(address(this));
        uint cMidBal = address(c).balance;

        // attempt Collect and detect revert
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after attempted collect
        (, uint afterBalance) = c.Acc(address(this));
        uint cAfterBal = address(c).balance;

        // general rule:
        // If Collect reverted -> we make no claim here (allow any behavior).
        // If Collect did not revert -> then either recorded balance unchanged, or it decreased by exactly collectAmount
        // and contract ether balance decreased by exactly collectAmount.
        // Express implication a -> b as (!a || b).
        bool cond;
        if (reverted) {
            cond = true;
        } else {
            bool unchanged = (midBalance == afterBalance) && (cMidBal == cAfterBal);
            bool decreased_properly = (midBalance >= afterBalance) && (midBalance - afterBalance == collectAmount) && (cMidBal >= cAfterBal) && (cMidBal - cAfterBal == collectAmount);
            cond = unchanged || decreased_properly;
        }

        assert(cond);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters for initialization, deposit, and collect amount.
    function run(address logAddress, uint minSum, uint lockTime, uint putAmount, uint collectAmount) public payable {
        // need funds to deposit
        require(address(this).balance >= putAmount);

        // initialize c only once: set log and min sum and mark initialized
        c.SetLogFile(logAddress);
        c.SetMinSum(minSum);
        c.Initialized();

        // read balances before deposit
        (, uint beforeBalance) = c.Acc(address(this));
        uint cBeforeBal = address(c).balance;

        // deposit funds into c; this may update the recorded balance
        c.Put{value: putAmount}(lockTime);

        // read balances after deposit, before collect
        (, uint midBalance) = c.Acc(address(this));
        uint cMidBal = address(c).balance;

        // attempt Collect and observe whether the external call to msg.sender succeeded
        bool callSucceeded = false;
        bool reverted = false;
        // use try/catch to detect revert; if it doesn't revert, we still need to know if the low-level call inside succeeded
        // The C.Collect performs an external call to msg.sender; when that call returns true the contract updates state.
        // If Collect reverts, nothing changed; if it returns without revert, either the internal call succeeded and state updated, or it failed and state unchanged.
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after collect
        (, uint afterBalance) = c.Acc(address(this));
        uint cAfterBal = address(c).balance;

        // We cannot directly observe whether the internal call inside Collect succeeded, but its observable effect
        // is that recorded balance decreased by collectAmount and contract balance decreased by collectAmount.
        // Our property: if Collect did NOT revert and both recorded and contract balances decreased by exactly collectAmount,
        // then that indicates the internal send succeeded. Conversely, if the send succeeded, these decreases must hold.
        // We assert: if Collect did not revert and the contract's recorded balance decreased, then it decreased exactly by collectAmount
        // and the contract's ether balance also decreased exactly by collectAmount.

        // Formulate as implication: (not reverted && midBalance > afterBalance) -> (midBalance - afterBalance == collectAmount && cMidBal - cAfterBal == collectAmount)
        bool implication = true;
        if (!reverted && midBalance > afterBalance) {
            // avoid underflow by comparing before subtracting
            implication = (midBalance - afterBalance == collectAmount) && (cMidBal >= cAfterBal) && (cMidBal - cAfterBal == collectAmount);
        }

        assert(implication);
    }

    // receive to accept refunds if any
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that a successful (non-reverting) Collect call never reduces the recorded balance by more than the requested amount.
    // Parameters: min sum and collect amount. We avoid calling Put to prevent triggering add_uint256 in c; we only use public getters and Collect.
    function run(uint minSum, uint collectAmount) public payable {
        // Set up c: set MinSum and mark initialized so Collect can run (these calls may revert if already initialized in some runs; that's fine for property testing environment with fresh c).
        c.SetMinSum(minSum);
        c.Initialized();

        // Read recorded balance before Collect
        (, uint beforeBal) = c.Acc(address(this));
        uint cBefore = address(c).balance;

        // Call Collect and detect whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read recorded balance and contract balance after Collect
        (, uint afterBal) = c.Acc(address(this));
        uint cAfter = address(c).balance;

        // If the call reverted, nothing needed; if it did not revert and the recorded balance decreased, ensure it did not decrease by more than collectAmount.
        // Avoid subtraction that could underflow by using comparisons.
        // Condition: either reverted OR afterBal >= beforeBal OR (beforeBal - afterBal) <= collectAmount
        bool ok;
        if (reverted) {
            ok = true;
        } else {
            if (afterBal >= beforeBal) {
                ok = true;
            } else {
                // beforeBal > afterBal, so safe to compute difference
                uint diff = beforeBal - afterBal;
                ok = (diff <= collectAmount) && (cBefore >= cAfter ? (cBefore - cAfter) <= collectAmount : true);
            }
        }

        assert(ok);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test that a call to Put with some lockTime and attached Ether increases both the contract's ether balance
    // and this caller's recorded balance in c by at least the amount sent (never decreases them).
    // We avoid any unsafe arithmetic in the test itself.
    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");

        // Ensure contract initialized settings won't interfere: set MinSum and mark initialized if desired.
        // These calls are allowed on a fresh c; if they revert the try/catch will capture it — but we don't need them for Put.
        // Record balances before the Put
        (, uint beforeRecorded) = c.Acc(address(this));
        uint cBefore = address(c).balance;

        // Perform Put sending `amount` wei.
        bool reverted;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after
        (, uint afterRecorded) = c.Acc(address(this));
        uint cAfter = address(c).balance;

        // General rule: If Put did not revert, then the contract's ether balance increased by exactly amount
        // and the recorded balance for this caller did not decrease (i.e., afterRecorded >= beforeRecorded),
        // and the contract balance increased by at least amount (use >= to avoid relying on external call behavior).
        // We avoid underflow by using comparisons only.
        assert(reverted || (cAfter >= cBefore && afterRecorded >= beforeRecorded && (cAfter - cBefore) >= amount));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will try to Put some funds, then set MinSum and unlock time such that Collect may succeed.
    // Params:
    // putAmount - amount of wei to send with Put
    // lockTime  - argument to Put (seconds to add to block.timestamp for unlock)
    // minsum    - value to set as MinSum before collecting
    // collectAmt - amount to attempt to collect
    function run(uint putAmount, uint lockTime, uint minsum, uint collectAmt) public payable {
        require(address(this).balance >= putAmount, "need funds to Put");

        // Initially set the log file to the existing LogFile in c if any by calling SetLogFile is optional.
        // We avoid calling SetLogFile/Initialized unless needed; instead just perform Put.

        // Record c and holder state before actions
        uint beforeContractBalance = address(c).balance;
        (uint beforeUnlock, uint beforeBalance) = _getHolder(msg.senderToHolder());

        // Perform Put sending putAmount wei
        c.Put{value: putAmount}(lockTime);

        // Set MinSum once (only allowed when not initialized). To avoid revert, only attempt if not initialized.
        // We cannot read internal 'intitalized' so we attempt SetMinSum in a try/catch to detect revert.
        bool setMinSucceeded;
        try c.SetMinSum(minsum) {
            setMinSucceeded = true;
        } catch {
            setMinSucceeded = false;
        }

        // Fast forward: We cannot change block.timestamp. To make Collect succeed we need block.timestamp > unlockTime.
        // Since we cannot advance time, we choose the property to account for both outcomes: when Collect succeeds (no revert), balances change appropriately.

        // Record balances before Collect
        uint beforeContractBalance2 = address(c).balance;
        (uint beforeUnlock2, uint beforeBalance2) = _getHolder(msg.senderToHolder());

        // Attempt Collect and capture whether it reverted
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after state
        uint afterContractBalance = address(c).balance;
        (uint afterUnlock, uint afterBalance) = _getHolder(msg.senderToHolder());

        // If Collect did not revert, then the holder's stored balance must have decreased by collectAmt
        // and the contract's balance must have decreased by at least collectAmt (sent out); if it reverted, nothing is required.
        assert( collectReverted || (afterBalance + collectAmt == beforeBalance2 && beforeContractBalance2 >= afterContractBalance + collectAmt - 0) );
    }

    // Helper: get holder for this contract's address via public getter Acc
    function _getHolder(address holderAddr) internal returns (uint, uint) {
        // The auto-generated getter for Acc returns (uint unlockTime, uint balance) as a tuple
        return c.Acc(holderAddr);
    }

    // Helper: msg.sender inside calls to c will be this contract; provide that address
    function msg.senderToHolder() internal view returns (address) {
        return address(this);
    }

    // Allow the test contract to receive Ether so it can fund Put
    receive() external payable {}
}

