contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Property: If Collect succeeds (does not revert), then
    // 1) the holder's stored balance (observable via c.Acc) does not increase (after <= before), and
    // 2) address(c).balance decreases by at least the amount attempted to collect.
    // We avoid any subtraction in the final assert that could underflow by comparing via addition.
    function run(uint am, uint dummyLock) public payable {
        // ensure we have funds to call Put if needed
        require(address(this).balance >= 1, "need some ether");

        // 1) initialize MinSum and Log and mark initialized so SetMinSum/SetLogFile can't be called later
        // We can call SetMinSum and SetLogFile before Initialized; they will revert if intitalized is true.
        // These calls may revert in some paths, but that's fine. They are independent from our Collect check.
        // Use try/catch to continue regardless.
        try c.SetMinSum(0) {
        } catch {}
        try c.SetLogFile(address(0)) {
        } catch {}
        try c.Initialized() {
        } catch {}

        // Make sure the InvMutTest contract has some stored balance in c so Collect might succeed
        // Send 1 wei to Put to create/augment Acc[msg.sender]
        if (address(this).balance >= 1) {
            // call Put to deposit 1 wei
            try c.Put{value: 1}(dummyLock) {
            } catch {}
        }

        // Read before-values
        uint beforeContractBal = address(c).balance;
        (uint beforeUnlock, uint beforeHolderBal) = c.Acc(address(this));

        // Attempt Collect(am)
        bool collectReverted;
        try c.Collect{value: 0}(am) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-values
        uint afterContractBal = address(c).balance;
        (uint afterUnlock, uint afterHolderBal) = c.Acc(address(this));

        // If Collect did not revert then (A) holder's recorded balance did not increase, and
        // (B) contract balance decreased by at least am (i.e., beforeContractBal >= afterContractBal and
        //     beforeContractBal <= afterContractBal + am is equivalent to afterContractBal >= beforeContractBal - am,
        //     but to avoid subtraction we check beforeContractBal <= afterContractBal + am)
        assert(collectReverted || (afterHolderBal <= beforeHolderBal && beforeContractBal <= afterContractBal + am));
    }

    // allow receiving ether if c sends Ether back
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing setup and the property check.
    // Params:
    //  am - amount to attempt to collect
    //  putVal - amount of wei to send to Put to ensure caller has some balance
    //  lock - lock time argument for Put
