        // SetMinSum and SetLogFile and Initialized are state-changing and must be top-level calls.
        c.SetMinSum(0);
        // Use this contract as the LogFile address; LogFile.AddMessage is public so passing our address is fine
        c.SetLogFile(address(this));
        c.Initialized();

        // Observe holder balance before Put
        C.Holder memory beforeHolder = c.Acc(address(this));
        uint beforeBalance = beforeHolder.balance;
        uint beforeContractBal = address(c).balance;

        // Send Ether to c via Put. Ensure this contract has enough balance for putAmount.
        // Must have address(this).balance >= putAmount
        require(address(this).balance >= putAmount, "need ETH to put");
        c.Put{value: putAmount}(putLock);

        // After Put, holder balance should have increased by putAmount
        C.Holder memory afterPutHolder = c.Acc(address(this));
        uint afterPutBalance = afterPutHolder.balance;
        uint afterPutContractBal = address(c).balance;

        // Attempt Collect and capture whether it reverted
        bool reverted;
        // Collect is payable in signature but does not require msg.value; we won't send value here
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read holder after Collect
        C.Holder memory afterCollectHolder = c.Acc(address(this));
        uint afterCollectBalance = afterCollectHolder.balance;
        uint afterCollectContractBal = address(c).balance;

        // If Collect did not revert then: (1) before conditions must have held: holder.balance >= MinSum && holder.balance >= collectAmount && block.timestamp > unlockTime
        // But we cannot inspect block.timestamp or unlockTime aside from holder.unlockTime. We assert the stronger observed invariant:
        // If Collect succeeded then the holder balance decreased by exactly collectAmount and the contract balance decreased by at least collectAmount.
        assert( reverted || (afterPutBalance >= collectAmount && // it must have had enough at time of call
                              afterCollectBalance + collectAmount == afterPutBalance &&
                              afterCollectContractBal + collectAmount <= afterPutContractBal ) );
    }

    // Minimal receive so LogFile.AddMessage calls that push Ether back won't revert
    receive() external payable { }
}

