contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to call Collect and assert that if it does not revert then
    // (1) the contract balance decreased by at least the collected amount, and
    // (2) the recorded holder balance decreased by at most the collected amount (i.e. not more than was withdrawn).
    // We avoid arithmetic underflow in the assertion by using only >= comparisons and differences where safe.
    function run(uint collectAmount, uint initialPut) public payable {
        // this test needs ETH to seed the contract for Put
        require(address(this).balance >= initialPut, "need ETH to seed");

        // initialize c so Put/Collect operate: set MinSum=0, set LogFile to this address and mark initialized
        c.SetMinSum(0);
        c.SetLogFile(address(this));
        c.Initialized();

        // Deposit initialPut into c so there is balance to collect later
        c.Put{value: initialPut}(0);

        // Read balances before Collect
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Try Collect and capture revert status
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after Collect attempt
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Collect succeeded then the contract's balance must have decreased by at least collectAmount
        // and the holder's recorded balance must not have decreased by more than collectAmount.
        // If Collect reverted then no further condition is required here.
        assert(reverted || (
            // contract balance decrease check (no underflow because afterContractBal <= beforeContractBal expected)
            (beforeContractBal >= afterContractBal && beforeContractBal - afterContractBal >= collectAmount)
            // holder balance decrease is at most collectAmount: beforeBalance >= afterBalance and difference <= collectAmount
            && (beforeBalance >= afterBalance && beforeBalance - afterBalance <= collectAmount)
        ));
    }

    // receive to accept ETH when c calls back (LogFile.AddMessage may send nothing, but keep to be safe)
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We call Put to fund the contract, then attempt Collect. If Collect does not revert,
    // then the recorded holder balance must not increase, and the decrease in contract balance
    // must be at least the decrease in the recorded holder balance. We avoid subtraction that can underflow
    // by using comparisons.
    function run(uint collectAmount, uint seedAmount) public payable {
        // need ETH to seed Put
        require(address(this).balance >= seedAmount, "need ETH");

        // initialize c so Put/Collect operate: set MinSum=0, set LogFile to this address and mark initialized
        c.SetMinSum(0);
        c.SetLogFile(address(this));
        c.Initialized();

        // Deposit seedAmount into c
        c.Put{value: seedAmount}(0);

        // Read balances before Collect
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Try Collect and capture revert status
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after Collect attempt
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // Assert general invariant: if Collect succeeded then holder balance did not increase,
        // and contract balance decreased by at least the holder balance decrease.
        // We express "holder did not increase" as afterBalance <= beforeBalance.
        // And "contract drop >= holder drop" as beforeContractBal >= afterContractBal and
        // (beforeContractBal - afterContractBal) >= (beforeBalance - afterBalance).
        // To avoid subtraction underflow in the assertion when comparing drops, we only assert
        // the latter when the before values are >= after values respectively.
        assert(reverted || (
            // holder balance did not increase
            afterBalance <= beforeBalance
            // contract balance did not increase
            && afterContractBal <= beforeContractBal
            // if both decreased, contract's decrease is at least holder's decrease
            && ( (beforeBalance >= afterBalance && beforeContractBal >= afterContractBal)
                 ? ( (beforeContractBal - afterContractBal) >= (beforeBalance - afterBalance) )
                 : true )
        ));
    }

    // Accept ETH if c sends any
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will try to Put some funds (value) and then attempt Collect(_am).
    // Parameters:
    // - putAmount: Ether to deposit into c via Put
    // - lockTime: lock time argument to Put
    // - am: amount to Collect
    function run(uint putAmount, uint lockTime, uint am) public payable {
        require(address(this).balance >= putAmount, "insufficient test balance for put");

        // initial observations
        uint beforeContractBal = address(c).balance;
        (uint accUnlockBefore, uint accBalBefore) = getAcc(address(this));
        uint minSum = c.MinSum();

        // perform Put with value putAmount
        c.Put{value: putAmount}(lockTime);

        // observe after Put
        uint afterContractBal = address(c).balance;
        (uint accUnlockMid, uint accBalMid) = getAcc(address(this));

        // record balances before Collect attempt
        uint beforeCollectContractBal = afterContractBal;
        uint accBalBeforeCollect = accBalMid;

        // attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect{value: 0}(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observations after Collect (whether succeeded or not)
        uint finalContractBal = address(c).balance;
        (uint accUnlockAfter, uint accBalAfter) = getAcc(address(this));

        // General rule:
        // If Collect succeeded (not reverted) then it must have transferred 'am' out of c to this contract,
        // and the recorded per-account balance must have decreased by exactly am.
        // If Collect reverted or did not meet conditions, balances must be unchanged from beforeCollect.
        // Also only allow the success case if preconditions held: accBalBeforeCollect >= minSum && accBalBeforeCollect >= am && block.timestamp > accUnlockMid

        bool preconditionsHold = (accBalBeforeCollect >= minSum) && (accBalBeforeCollect >= am) && (block.timestamp > accUnlockMid);

        // If reverted then either preconditions failed or some external send failed; in either case acc balance should be unchanged
        // If not reverted and preconditionsHold then contract balance reduced by am and account balance reduced by am
        assert(
            reverted
            ? (accBalAfter == accBalBeforeCollect && finalContractBal == beforeCollectContractBal)
            : (preconditionsHold && accBalAfter + am == accBalBeforeCollect && finalContractBal + am == beforeCollectContractBal)
        );
    }

    // helper to read the public Acc getter (auto-generated mapping getter returns (uint unlockTime, uint balance))
    function getAcc(address a) internal returns (uint, uint) {
        (uint u, uint b) = c.Acc(a);
        return (u, b);
    }

    // receive to accept refunds/transfers
    receive() external payable {}
}

