contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test Collect: caller must have at least MinSum and sufficient recorded balance and a past unlockTime to succeed.
    // Parameters:
    //  - preFund: Ether to fund the contract via Put so Acc.balance >= MinSum and >= collectAmount
    //  - lockTime: lockTime to pass to Put (we will use 0 to allow immediate collect when desired)
    //  - collectAmount: amount to attempt to Collect
    function run(uint preFund, uint lockTime, uint collectAmount) public payable {
        require(address(this).balance >= preFund, "insufficient test balance");

        // Initialize required settings on c: set MinSum and mark initialized and set a LogFile (zero address allowed)
        // These calls may revert if intitalized already set, but since c is fresh they should succeed.
        // Set a MinSum small enough (use 1) only if preFund > 0; otherwise set MinSum = 0.
        uint minVal = preFund == 0 ? 0 : 1;
        c.SetMinSum(minVal);
        c.SetLogFile(address(0));
        c.Initialized();

        // Observe before balances
        uint beforeContractBal = address(c).balance;
        (, uint accBalBefore) = c.Acc(address(this));

        // Fund the contract/account by calling Put with value = preFund
        if (preFund > 0) {
            require(address(this).balance >= preFund);
            c.Put{value: preFund}(lockTime);
        }

        // After funding, read balances again
        uint fundedContractBal = address(c).balance;
        (, uint accBalAfterFund) = c.Acc(address(this));

        // Try to Collect collectAmount and capture whether it reverted
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after collect attempt
        uint afterContractBal = address(c).balance;
        (, uint accBalAfterCollect) = c.Acc(address(this));

        // The rule: if Collect succeeded then collectAmount must be > 0 and both the contract balance
        // and the recorded Acc balance decreased by exactly collectAmount; otherwise (reverted) both
        // balances remain equal to their post-fund values. This avoids doing subtraction in the assert
        // by comparing sums.
        assert(
            (!reverted && collectAmount > 0 && fundedContractBal == afterContractBal + collectAmount && accBalAfterFund == accBalAfterCollect + collectAmount)
            || (reverted && fundedContractBal == afterContractBal && accBalAfterFund == accBalAfterCollect)
        );
    }

    // Allow receiving ETH when c sends funds back
    receive() external payable {}
}
